function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(base64);
  return Uint8Array.from(raw, char => char.charCodeAt(0));
}

const defaults = { ...EXTRA_DEFAULTS, darkerMode: false, theme: 'yellow', density: 'comfortable', fontSize: 14, reducedMotion: false, enterToSend: true, notifications: false, sound: false, showBuddy: true, showTimestamps: true, showAvatars: true, showReactions: true, showEditedTags: true, showReplyPreviews: true, showAttachmentPreviews: true, showMessageTools: true, showComposerHint: true, showMessageBorders: true, fontFamily: 'dm-sans', lineHeight: 'normal', attachmentShape: 'rounded', underlineLinks: true };

function loadSettings(userId) {
  try { return { ...defaults, ...JSON.parse(localStorage.getItem('defchat:preferences:' + userId) || '{}') }; }
  catch { return defaults; }
}

function downloadFile(name, content, type) {
  const blob = new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export default function PowerFeatures({ open, onClose, db, userId, messages = [], conversationTitle = 'conversation', onOpenSearch, onToggleEmoji }) {
  const [settings, setSettings] = useState(() => loadSettings(userId));
  const [notice, setNotice] = useState('');
  const [tab, setTab] = useState('appearance');
  const [extraSearch, setExtraSearch] = useState('');
  const [extraGroup, setExtraGroup] = useState('All');
  const safeTitle = useMemo(() => String(conversationTitle || 'conversation').replace(/[^a-z0-9-_]+/gi, '-').replace(/^-|-$/g, '').slice(0, 50) || 'conversation', [conversationTitle]);

  useEffect(() => { setSettings(loadSettings(userId)); }, [userId]);
  useEffect(() => {
    try { localStorage.setItem('defchat:preferences:' + userId, JSON.stringify(settings)); } catch {}
    const theme = THEMES.find(item => item.id === settings.theme) || THEMES[0];
    document.documentElement.style.setProperty('--dc-yellow', theme.color);
    document.documentElement.style.setProperty('--dc-solar-glow', theme.color + '24');
    document.documentElement.style.setProperty('--dc-accent', theme.color);
    document.documentElement.dataset.darkerMode = settings.darkerMode ? 'true' : 'false';
    document.documentElement.dataset.chatDensity = settings.density;
    document.documentElement.dataset.chatMotion = settings.reducedMotion ? 'reduced' : 'full';
    document.documentElement.style.setProperty('--dc-message-size', settings.fontSize + 'px');
    document.documentElement.dataset.showTimestamps = settings.showTimestamps ? 'true' : 'false';
    document.documentElement.dataset.showAvatars = settings.showAvatars ? 'true' : 'false';
    document.documentElement.dataset.showReactions = settings.showReactions ? 'true' : 'false';
    document.documentElement.dataset.showEditedTags = settings.showEditedTags ? 'true' : 'false';
    document.documentElement.dataset.showReplyPreviews = settings.showReplyPreviews ? 'true' : 'false';
    document.documentElement.dataset.showAttachmentPreviews = settings.showAttachmentPreviews ? 'true' : 'false';
    document.documentElement.dataset.showMessageTools = settings.showMessageTools ? 'true' : 'false';
    document.documentElement.dataset.showComposerHint = settings.showComposerHint ? 'true' : 'false';
    document.documentElement.dataset.showMessageBorders = settings.showMessageBorders ? 'true' : 'false';
    document.documentElement.dataset.fontFamily = settings.fontFamily;
    const fontFamilies = { 'dm-sans': "'DM Sans', sans-serif", inter: "'Inter', sans-serif", roboto: "'Roboto', sans-serif", nunito: "'Nunito Sans', sans-serif", 'space-grotesk': "'Space Grotesk', sans-serif", hyperlegible: "'Atkinson Hyperlegible', sans-serif", mono: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace" };
    document.documentElement.style.setProperty('--dc-custom-font', fontFamilies[settings.fontFamily] || fontFamilies['dm-sans']);
    document.documentElement.dataset.messageLineHeight = settings.lineHeight;
    document.documentElement.dataset.attachmentShape = settings.attachmentShape;
    document.documentElement.dataset.underlineLinks = settings.underlineLinks ? 'true' : 'false';
    EXTRA_SETTINGS.forEach(item => { document.documentElement.dataset[item.key] = String(settings[item.key] ?? item.defaultValue); });
    document.documentElement.style.setProperty('--dc-interface-scale', String(settings.interfaceScale ?? 100) + '%');
    document.documentElement.style.setProperty('--dc-media-radius', String(settings.mediaCornerRadius ?? 10) + 'px');
  }, [settings, userId]);
  useEffect(() => {
    const handle = event => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault(); onOpenSearch?.();
      } else if ((event.ctrlKey || event.metaKey) && event.key === ',') {
        event.preventDefault(); window.dispatchEvent(new CustomEvent('defchat:open-power-settings'));
      } else if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key.toLowerCase() === 'e') {
        event.preventDefault(); onToggleEmoji?.();
      } else if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key.toLowerCase() === 'm') {
        event.preventDefault(); document.querySelector('.composer input:not([type=file])')?.focus();
      } else if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key.toLowerCase() === 'b') { event.preventDefault(); window.dispatchEvent(new CustomEvent('defchat:open-saved-messages')); } else if (event.key === 'Escape' && open) onClose?.();
    };
    window.addEventListener('keydown', handle);
    return () => window.removeEventListener('keydown', handle);
  }, [open, onClose, onOpenSearch, onToggleEmoji]);

  function change(key, value) { setSettings(current => ({ ...current, [key]: value })); if (key === 'showBuddy') window.dispatchEvent(new CustomEvent('defchat:buddy-visibility', { detail: { visible: value } })); setNotice('Preference saved on this device.'); }
  async function enableNotifications() {
    if (settings.notifications) {
      try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.getSubscription();
        if (subscription) {
          const { error } = await db.functions.invoke('send-push', { body: { action: 'unsubscribe', endpoint: subscription.endpoint } });
          if (error) throw error;
          await subscription.unsubscribe();
        }
        change('notifications', false);
        setNotice('Background notifications are turned off on this device.');
      } catch (error) {
        setNotice(error?.message || 'Could not turn off background notifications.');
      }
      return;
    }
    if (!('Notification' in window)) { setNotice('Notifications are not supported by this browser.'); return; }
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      setNotice('Background push is not supported here. Try installing defchat on your device and enabling notifications there.');
      return;
    }
    try {
      const permission = await Notification.requestPermission();
      if (permission !== 'granted') {
        change('notifications', false);
        setNotice(permission === 'denied' ? 'Notifications are blocked for this site. Allow them in your browser or device settings, then try again.' : 'Notification permission was not granted.');
        return;
      }
      const registration = await navigator.serviceWorker.ready;
      const { data: keyData, error: keyError } = await db.functions.invoke('send-push', { body: { action: 'public-key' } });
      if (keyError || !keyData?.publicKey) throw keyError || new Error('Could not load the push notification key.');
      const applicationServerKey = urlBase64ToUint8Array(keyData.publicKey);
      let subscription = await registration.pushManager.getSubscription();
      if (!subscription) subscription = await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey });
      const { error } = await db.functions.invoke('send-push', { body: { action: 'subscribe', subscription: subscription.toJSON() } });
      if (error) {
        await subscription.unsubscribe().catch(() => {});
        throw error;
      }
      change('notifications', true);
      setNotice('Background push notifications are enabled. You can close defchat and still receive new messages and friend requests.');
    } catch (error) {
      setNotice(error?.message || 'Could not enable background push notifications. Check site permissions and try again.');
    }
  }
  function exportMessages(format) {
    const rows = messages.map(message => ({
      author: message.profiles?.username || 'member',
      createdAt: message.created_at || '',
      content: message.content || '',
      attachment: message.attachment_url || '',
      edited: Boolean(message.edited_at),
    }));
    if (format === 'json') downloadFile('defchat-' + safeTitle + '.json', JSON.stringify({ app: 'defchat', exportedAt: new Date().toISOString(), conversation: conversationTitle, messages: rows }, null, 2), 'application/json;charset=utf-8');
    if (format === 'txt') downloadFile('defchat-' + safeTitle + '.txt', rows.map(row => '[' + (row.createdAt ? new Date(row.createdAt).toLocaleString() : 'unknown time') + '] ' + row.author + ': ' + row.content + (row.attachment ? '\nAttachment: ' + row.attachment : '')).join('\n\n'), 'text/plain;charset=utf-8');
    if (format === 'csv') {
      const cell = value => '"' + String(value ?? '').replace(/"/g, '""') + '"';
      const csv = [['Author', 'Created at', 'Message', 'Attachment', 'Edited'], ...rows.map(row => [row.author, row.createdAt, row.content, row.attachment, row.edited])].map(row => row.map(cell).join(',')).join('\r\n');
      downloadFile('defchat-' + safeTitle + '.csv', '\ufeff' + csv, 'text/csv;charset=utf-8');
    }
    setNotice('Your export is ready.');
  }

  if (!open) return null;
  return <div className="modal-backdrop power-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) onClose?.(); }}>
    <section className="power-modal" role="dialog" aria-modal="true" aria-labelledby="power-title">
      <header className="power-heading"><span className="power-heading-icon"><SlidersHorizontal size={20}/></span><div><small>DEFGODQE / PERSONALIZE</small><h2 id="power-title">Power settings</h2><p>Your preferences, your workspace.</p></div><button className="modal-close" onClick={onClose} aria-label="Close settings"><X size={19}/></button></header>
      <div className="power-tabs">
        <button className={tab === 'appearance' ? 'active' : ''} onClick={() => setTab('appearance')}><Palette size={16}/> Appearance</button>
        <button className={tab === 'behavior' ? 'active' : ''} onClick={() => setTab('behavior')}><SlidersHorizontal size={16}/> Behavior</button>
        <button className={tab === 'export' ? 'active' : ''} onClick={() => setTab('export')}><Download size={16}/> Export data</button>
        <button className={tab === 'shortcuts' ? 'active' : ''} onClick={() => setTab('shortcuts')}><Keyboard size={16}/> Shortcuts</button>
        <button className={tab === 'extras' ? 'active' : ''} onClick={() => setTab('extras')}><SlidersHorizontal size={16}/> 100 more settings</button>
      </div>
      <div className="power-body">
        {tab === 'appearance' && <>
          <Toggle label="Extra dark mode" description="Use deeper black and charcoal surfaces across the app. Your choice is saved on this device." checked={settings.darkerMode} onChange={value => change('darkerMode', value)} />
          <div className="power-section-title"><h3>Accent color</h3><p>Choose a color for highlights and active controls.</p></div>
          <div className="power-themes">{THEMES.map(theme => <button key={theme.id} className={settings.theme === theme.id ? 'power-theme selected' : 'power-theme'} onClick={() => change('theme', theme.id)}><span style={{ background: theme.color }} />{theme.label}{settings.theme === theme.id && <Check size={15}/>}</button>)}</div>
          <div className="power-section-title"><h3>Chat density</h3><p>Choose how much space messages use.</p></div>
          <div className="power-segment"><button className={settings.density === 'comfortable' ? 'active' : ''} onClick={() => change('density', 'comfortable')}>Comfortable</button><button className={settings.density === 'compact' ? 'active' : ''} onClick={() => change('density', 'compact')}>Compact</button></div>
          <div className="power-setting"><div><b>Message text size</b><small>Adjust chat readability.</small></div><div className="power-size"><button onClick={() => change('fontSize', Math.max(12, settings.fontSize - 1))} aria-label="Decrease text size">−</button><strong>{settings.fontSize}px</strong><button onClick={() => change('fontSize', Math.min(18, settings.fontSize + 1))} aria-label="Increase text size">+</button></div></div>
          <Toggle label="Reduce animations" description="Use calmer transitions throughout the app." checked={settings.reducedMotion} onChange={value => change('reducedMotion', value)} />
          <Toggle label="Show message timestamps" description="Display the date and time beside each message." checked={settings.showTimestamps} onChange={value => change('showTimestamps', value)} />
          <Toggle label="Show message avatars" description="Show profile pictures next to chat messages." checked={settings.showAvatars} onChange={value => change('showAvatars', value)} />
          <Toggle label="Show quick reactions" description="Show the reaction row under channel messages." checked={settings.showReactions} onChange={value => change('showReactions', value)} />
          <Toggle label="Show edited labels" description="Hide the small edited marker after messages." checked={settings.showEditedTags} onChange={value => change('showEditedTags', value)} />
          <Toggle label="Show reply previews" description="Show the quoted message above a reply." checked={settings.showReplyPreviews} onChange={value => change('showReplyPreviews', value)} />
          <Toggle label="Show attachment previews" description="Show image previews in chat instead of links only." checked={settings.showAttachmentPreviews} onChange={value => change('showAttachmentPreviews', value)} />
          <Toggle label="Show message action buttons" description="Show save, reply, edit, and delete controls on messages." checked={settings.showMessageTools} onChange={value => change('showMessageTools', value)} />
          <Toggle label="Show composer tips" description="Show formatting hints below the message box." checked={settings.showComposerHint} onChange={value => change('showComposerHint', value)} />
          <Toggle label="Show subtle message borders" description="Add a light outline around chat messages." checked={settings.showMessageBorders} onChange={value => change('showMessageBorders', value)} />
          <div className="power-setting power-font-setting"><div><b>Custom font</b><small>Change the typeface used across the app. Your choice is saved on this device.</small></div><select className="power-font-select" aria-label="Choose app font" value={settings.fontFamily} onChange={event => change('fontFamily', event.target.value)}><option value="dm-sans">DM Sans · Default</option><option value="inter">Inter · Modern</option><option value="roboto">Roboto · Clean</option><option value="nunito">Nunito Sans · Rounded</option><option value="space-grotesk">Space Grotesk · Futuristic</option><option value="hyperlegible">Atkinson Hyperlegible · Accessible</option><option value="mono">Monospace · Developer</option></select></div>
          <div className="power-setting"><div><b>Message line spacing</b><small>Choose compact or relaxed reading.</small></div><div className="power-segment"><button className={settings.lineHeight === 'normal' ? 'active' : ''} onClick={() => change('lineHeight', 'normal')}>Normal</button><button className={settings.lineHeight === 'relaxed' ? 'active' : ''} onClick={() => change('lineHeight', 'relaxed')}>Relaxed</button></div></div>
          <div className="power-setting"><div><b>Attachment corners</b><small>Choose rounded or square image previews.</small></div><div className="power-segment"><button className={settings.attachmentShape === 'rounded' ? 'active' : ''} onClick={() => change('attachmentShape', 'rounded')}>Rounded</button><button className={settings.attachmentShape === 'square' ? 'active' : ''} onClick={() => change('attachmentShape', 'square')}>Square</button></div></div>
          <Toggle label="Underline links" description="Make clickable links stand out in messages." checked={settings.underlineLinks} onChange={value => change('underlineLinks', value)} />
        </>}
        {tab === 'behavior' && <>
          <div className="power-section-title"><h3>Chat behavior</h3><p>Fine-tune how messages are composed and alerts work.</p></div>
          <Toggle label="Show Buddy mascot" description="Turn Buddy on or off anywhere in defchat. You can change this any time." checked={settings.showBuddy} onChange={value => change('showBuddy', value)} />
          <Toggle label="Enter sends messages" description="When disabled, use the send button instead." checked={settings.enterToSend} onChange={value => change('enterToSend', value)} />
          <Toggle label="Enable message sound" description="Preference saved for future sound integrations." checked={settings.sound} onChange={value => change('sound', value)} icon={<Volume2 size={17}/>} />
          <div className="power-setting"><div><b>Background push notifications</b><small>Receive message and friend-request alerts even when defchat is closed. Requires browser/device notification permission.</small></div><button className="power-secondary" onClick={enableNotifications}><Bell size={15}/> {settings.notifications ? 'Disable' : 'Enable'}</button></div>
          <div className="power-safe-note"><ShieldCheck size={17}/><span>Notification preferences are saved on this device. Web push works in supported browsers; on iPhone, add defchat to your Home Screen first.</span></div>
        </>}
        {tab === 'export' && <>
          <div className="power-section-title"><h3>Export current conversation</h3><p>Download the messages currently loaded in this view ({messages.length}). Exports are created on your device.</p></div>
          <div className="power-export-grid"><button onClick={() => exportMessages('json')}><Download size={18}/><b>JSON archive</b><small>Structured data and metadata</small></button><button onClick={() => exportMessages('txt')}><Download size={18}/><b>Plain text</b><small>Easy to read or share</small></button><button onClick={() => exportMessages('csv')}><Download size={18}/><b>CSV spreadsheet</b><small>Open in Excel or Sheets</small></button></div>
          <div className="power-safe-note"><ShieldCheck size={17}/><span>Only the messages currently loaded in the app are included. Attachments are linked, not downloaded. Export files may contain private conversations—store them carefully.</span></div>
        </>}
        {tab === 'shortcuts' && <>
          <div className="power-section-title"><h3>Keyboard shortcuts</h3><p>Jump around defchat without leaving the keyboard.</p></div>
          <div className="power-shortcuts">{[['Ctrl / ⌘ + K','Search messages'],['Ctrl / ⌘ + ,','Open power settings'],['Ctrl / ⌘ + Shift + M','Focus message composer'],['Ctrl / ⌘ + Shift + E','Open emoji picker'],['Ctrl / ⌘ + Shift + B','Open saved messages'],['Esc','Close the current settings dialog']].map(([keys, label]) => <div className="power-shortcut" key={keys}><span>{label}</span><kbd>{keys}</kbd></div>)}</div>
          <button className="power-secondary" onClick={() => { onClose?.(); onOpenSearch?.(); }}><Search size={16}/> Try message search</button>
        </>}

        {tab === 'extras' && <>
          <div className="power-section-title"><h3>100 more settings</h3><p>Fine-tune your solar workspace. Changes save automatically on this device.</p></div>
          <label className="extra-settings-search"><Search size={16}/><input value={extraSearch} onChange={event => setExtraSearch(event.target.value)} placeholder="Search all 100 settings…" aria-label="Search extra settings"/></label>
          <div className="extra-settings-filters"><button className={extraGroup === 'All' ? 'active' : ''} onClick={() => setExtraGroup('All')}>All 100</button>{[...new Set(EXTRA_SETTINGS.map(item => item.group))].map(group => <button key={group} className={extraGroup === group ? 'active' : ''} onClick={() => setExtraGroup(group)}>{group}</button>)}</div>
          <div className="extra-settings-list">{EXTRA_SETTINGS.filter(item => (extraGroup === 'All' || item.group === extraGroup) && (item.label + ' ' + item.description + ' ' + item.group).toLowerCase().includes(extraSearch.toLowerCase())).map(item => <div className="power-setting extra-setting" key={item.key}><div className="extra-setting-main"><div className="extra-setting-copy"><b>{item.label}</b><small>{item.description}</small><span className="extra-setting-group">{item.group}</span></div><div className="extra-setting-control">{item.type === 'toggle' ? <button type="button" className={settings[item.key] ? 'power-toggle on' : 'power-toggle'} role="switch" aria-checked={Boolean(settings[item.key])} aria-label={item.label} onClick={() => change(item.key, !settings[item.key])}><i/></button> : item.type === 'select' ? <select aria-label={item.label} value={settings[item.key] ?? item.defaultValue} onChange={event => change(item.key, event.target.value)}>{item.options.map(([label, value]) => <option key={value} value={value}>{label}</option>)}</select> : <div className="extra-range"><input type="range" min={item.min} max={item.max} step={item.step} value={settings[item.key] ?? item.defaultValue} aria-label={item.label} onChange={event => change(item.key, Number(event.target.value))}/><b>{settings[item.key] ?? item.defaultValue}{item.key === 'interfaceScale' ? '%' : item.key === 'mediaCornerRadius' ? 'px' : item.key === 'notificationSoundVolume' ? '%' : ''}</b></div>}</div></div><SettingPreview item={item} value={settings[item.key] ?? item.defaultValue}/></div>)}</div>
          <div className="power-safe-note"><ShieldCheck size={17}/><span>These 100 extra preferences save per user on this device. Visual controls apply where supported by the current interface; notification, privacy, and cross-device options that need server-side support remain preferences until those integrations are connected.</span></div>
        </>}
        {notice && <div className="power-notice" role="status">{notice}<button onClick={() => setNotice('')} aria-label="Dismiss notice"><X size={13}/></button></div>}
      </div>
      <footer className="power-footer"><span>defchat · Personal workspace</span><button className="primary" onClick={onClose}>Done</button></footer>
    </section>
  </div>;
}


function SettingPreview({ item, value }) {
  const enabled = item.type === 'toggle' ? Boolean(value) : !['off', 'none', 'minimal', 'reduced', 'private'].includes(String(value));
  const selectedLabel = item.type === 'select' ? (item.options.find(option => option[1] === value)?.[0] || String(value)) : item.type === 'range' ? String(value) + (item.key === 'interfaceScale' || item.key === 'notificationSoundVolume' ? '%' : item.key === 'mediaCornerRadius' ? 'px' : '') : (enabled ? 'On' : 'Off');
  return <div className={'setting-preview setting-preview-' + item.group.toLowerCase()} aria-label={'Illustrative preview for ' + item.label}>
    <div className="setting-preview-heading"><span><span className="setting-preview-dot"/> Live preview</span><b>{selectedLabel}</b></div>
    {item.group === 'Appearance' && <div className={'preview-surface ' + (enabled ? 'is-enabled' : '')} style={{ transform: item.key === 'interfaceScale' ? 'scale(' + (Number(value) / 100) + ')' : undefined, borderRadius: item.key === 'surfaceStyle' ? (value === 'sharp' ? 2 : value === 'rounded' ? 16 : 8) : 9 }}><span className="preview-sun"/> <i/><i/><i/></div>}
    {item.group === 'Messages' && <div className={'preview-chat ' + (enabled ? 'is-enabled' : '')}><div className="preview-avatar"/> <div className="preview-chat-lines"><b>{item.key === 'showAuthorBadges' && !enabled ? 'member' : 'SolarFox'} <em>{item.key === 'showAuthorBadges' && enabled ? '✦ MEMBER' : ''}</em></b><span className={item.key === 'emphasizeMentions' && enabled ? 'preview-mention' : ''}>{item.key === 'emphasizeMentions' ? '@you check this out!' : item.key === 'showLinkCards' && enabled ? 'example.com  · link preview' : 'Hey! Here is a sample message.'}</span>{item.key === 'showDateSeparators' && enabled && <small>— Today —</small>}</div></div>}
    {item.group === 'Composer' && <div className={'preview-composer ' + (enabled ? 'is-enabled' : '')}>{item.key === 'showFormattingToolbar' && enabled && <small>B　I　U　↗</small>}<span>{item.key === 'showTypingHint' && enabled ? 'Markdown is supported…' : 'Write a message…'}</span><b>{item.key === 'showSendButtonLabel' && enabled ? 'Send' : '➤'}</b></div>}
    {item.group === 'Accessibility' && <div className={'preview-accessibility ' + (enabled ? 'is-enabled' : '')}><b>Aa</b><span style={{letterSpacing: item.key === 'readingFriendlySpacing' && enabled ? '0.08em' : undefined, textDecoration: item.key === 'underlineAllLinks' && enabled ? 'underline' : undefined}}>Readable sample text</span><u>Example link</u></div>}
    {item.group === 'Notifications' && <div className={'preview-notification ' + (enabled ? 'is-enabled' : '')}><span className="preview-notification-icon">☼</span><div><b>{item.key === 'notificationPreviewDetail' && value !== 'full' ? 'New notification' : 'SolarFox sent a message'}</b><small>{item.key === 'notificationPreviewDetail' && value === 'minimal' ? 'New activity' : 'Hey, are you online?'}</small></div>{item.key === 'showNotificationBadge' && enabled && <i>2</i>}</div>}
    {item.group === 'Privacy' && <div className="preview-privacy"><span className="preview-avatar-small"/><div><b>{item.key === 'maskEmailInProfilePreference' && enabled ? 'd••••@mail.com' : 'SolarFox'}</b><small>{item.key === 'hideOnlineStatusPreference' && enabled ? 'Status hidden' : item.key === 'profileDiscoverabilityPreference' ? 'Visible to ' + selectedLabel.toLowerCase() : 'Profile visibility preview'}</small></div><span className="preview-lock">{enabled ? '◉' : '○'}</span></div>}
    {item.group === 'Navigation' && <div className={'preview-navigation ' + (enabled ? 'is-enabled' : '')}><span>☼ {item.key === 'showNavigationLabels' && !enabled ? '' : 'Home'}</span><span>▣ {item.key === 'showNavigationLabels' && !enabled ? '' : 'Messages'}</span><span>◉ {item.key === 'showNavigationLabels' && !enabled ? '' : 'Friends'}</span></div>}
    {item.group === 'Media' && <div className="preview-media" style={{ borderRadius: item.key === 'mediaCornerRadius' ? Number(value) : 10, width: item.key === 'mediaPreviewSize' ? (value === 'large' ? '100%' : value === 'medium' ? '76%' : '54%') : '76%' }}><span>☼</span><small>{item.key === 'imagePreviewFit' ? 'Image fit: ' + selectedLabel : 'Image / GIF preview'}</small></div>}
    {item.group === 'Profile' && <div className="preview-profile"><span className={'preview-profile-avatar ' + (item.key === 'profileAvatarShape' ? String(value) : '')} style={{ boxShadow: item.key === 'profileRingGlow' && enabled ? '0 0 0 3px #ffc83d, 0 0 12px #ffc83d' : undefined }}>S</span><div><b>SolarFox {item.key === 'showProfileBadges' && enabled ? '✦' : ''}</b><small>{item.key === 'showProfileBio' && enabled ? 'Building something bright.' : 'Profile preview'}</small></div><span className="preview-frame">{item.key === 'profileFrameAnimation' ? selectedLabel + ' frame' : 'PROFILE'}</span></div>}
    {item.group === 'Advanced' && <div className="preview-advanced"><span className={enabled ? 'preview-status-on' : ''}/><b>{item.key === 'performanceMode' ? selectedLabel + ' mode' : item.key === 'preferenceSyncPreference' ? 'Sync: ' + selectedLabel : item.key === 'localCachePreference' ? 'Cache: ' + selectedLabel : 'Preference state'}</b><small>{item.type === 'toggle' ? (enabled ? 'Enabled' : 'Disabled') : 'Example setting state'}</small></div>}
    <small className="setting-preview-caption">{item.group === 'Privacy' || item.group === 'Notifications' || item.group === 'Advanced' ? 'Illustration only · this preference may need additional integration' : 'Illustrative sample · shows the selected style'}</small>
  </div>;
}

function Toggle({ label, description, checked, onChange, icon }) {
  return <div className="power-setting"><div className="power-setting-label">{icon}{<span><b>{label}</b><small>{description}</small></span>}</div><button type="button" className={checked ? 'power-toggle on' : 'power-toggle'} role="switch" aria-checked={checked} aria-label={label} onClick={() => onChange(!checked)}><i/></button></div>;
}
